程设上机上周的第八题分数类为什么本地能跑但交上去却WA呀
#include <iostream>
using namespace std;
int gcd(int x, int y){
	return x%y==0?y:gcd(y,x%y);
}
class Fraction
{
    int num, den;
public:
// 在此处补充你的代码
Fraction(int a,int b):num(a),den(b){
    int GCD=gcd(num,den);
    num/=GCD;
    den/=GCD;
    if(den<0)
    {
        num=-num;
        den=-den;
    }
}
Fraction(int a):num(a),den(1){}
Fraction& operator*=(const Fraction& other){
    this->num*=other.num;
    this->den*=other.den;
    int GCD=gcd(abs(num),abs(den));
    num/=GCD;
    den/=GCD;
    return *this;
}
Fraction& operator/=(const Fraction& other){
    this->num*=other.den;
    this->den*=other.num;
    int GCD=gcd(abs(num),abs(den));
    num/=GCD;
    den/=GCD;
    if(den<0){
        num=-num;
        den=-den;
    }
    return *this;
}
Fraction operator*(const Fraction&other)const{//不应改变原来的对象
    int newNum = num * other.num;
    int newDen = den * other.den;
    int GCD = gcd(abs(newNum), abs(newDen));
    return Fraction(newNum / GCD, newDen / GCD);
}//返回引用的前提是对象本身存在
Fraction operator/(const Fraction& other)const{
    int newNum = num * other.den;
    int newDen = den * other.num;
    int GCD = gcd(abs(newNum), abs(newDen));
    return Fraction(newNum / GCD, newDen / GCD);
}
Fraction& operator=(const Fraction& other){
    num=other.num;
    den=other.den;
    return *this;
}
friend ostream&operator<<(ostream& cout,const Fraction& other){
    if(other.den==1){
        cout<<other.num;
        
    }
    else
    cout<<other.num<<"/"<<other.den;
    return cout;
}
operator float()
{
    return 1.0*num/den;
}
};
 
int main() {
	int a,b,c;
	cin >> a >> b >> c;
    Fraction f(a, b), g(c);
	f *= g;
	cout << f << endl;
	f /= g;
	cout << f << endl;
	f = f * f;
	cout << f << endl;
	f = f / g;
	cout << f << endl;
	cout << (float) f << endl;
    return 0;
}求大佬指点
